    p.loadState = function (x) { return { securityOk: !!x.ok('g1a1') && !!x.ok('g1a2') && !!x.ok('g1a3'), dg: false, heavy: false, uwsOk: !!x.d.uwsOk, customsOk: !!x.d.cus }; };
