  function I(id, title, at, cards, x) { return Object.assign({ id: id, title: title, at: at, cards: cards }, x || {}); }
  function RD(id, x) { return AC(id, L('回答を読む', '회신 읽기', 'Read the reply'), L('読んだ', '읽었다', 'Read'), Object.assign({ cost: 3 }, x || {})); }
