  function capWithdraw(confirmed, id, reason) { var has = (confirmed || []).some(function (x) { return x.id === id; }); if (!has) return { ok: false, why: 'not-confirmed', list: confirmed }; if (WITHDRAW_OK.indexOf(reason) < 0) return { ok: false, why: 'no-reason', list: confirmed }; return { ok: true, list: confirmed.filter(function (x) { return x.id !== id; }) }; }
