    p.px = kr ? [{ id: 'd1', t: 'DEPA', name: 'PEREZ/LUIS', esc: 1, liable: false, keeperOrder: false }, { id: 'd2', t: 'DEPA', name: 'HASSAN/OMAR', esc: 1, liable: false, keeperOrder: false }]
              : [{ id: 'd1', t: 'DEPA', name: 'NGUYEN/VAN AN', esc: 1, liable: false, keeperOrder: false }, { id: 'd2', t: 'DEPA', name: 'OKAFOR/DANIEL', esc: 1, liable: false, keeperOrder: false }];
