  var ndNotam = function (id, ap, q, b, c, e, ko, ja, en) { return { id: id, ap: ap, txt: id + ' NOTAMN\nQ)' + q + '\nA)' + ap + ' B)' + b + ' C)' + c + '\nE)' + e, why: L(ja, ko, en) }; };
