      KR: { flight: 'VELA 302', from: 'ICN', to: 'NRT', toName: L('成田', '나리타', 'Narita'), std: TIMES.KR.std, start: TIMES.KR.start, close: TIMES.KR.close, board: TIMES.KR.board, gate: TIMES.KR.gate, t: TIMES.KR, pax: function () { return units('KR'); } }
