    var V3 = { wch: { need: r() < .5 ? 'WCHR' : 'WCHS', own: r() < .5 }, um: { blank: r() < .5 }, pet: { kind: ['ok', 'ok', 'over', 'docs'][Math.floor(r() * 4)] }, preg: pregV };
