  var U = window.MISSION_CI02._u, A2 = window.MISSION_CI02.aircraft;

  /* 연결편(교육용 가상 편명). cnx = 원래 연결 시간, 지연 후 연결 시간은 게임이 dep − eta 로 계산 */
