    s += '<ellipse cx="-15" cy="' + (ey + 8) + '" rx="4.5" ry="2.6" fill="#f3a9a0" opacity=".6"/><ellipse cx="15" cy="' + (ey + 8) + '" rx="4.5" ry="2.6" fill="#f3a9a0" opacity=".6"/>';
