        sfx.ok(); c.flags.ppFixed = true; c.flags.ppBusy = true;
        say('me', L('恐れ入ります、旅券のお写真をもう一度確認させてください。', '죄송합니다, 여권 사진을 다시 확인하겠습니다.', 'Excuse me, let me check the passport photo once more.'));
