      if (!str(r.tab) || ['prep', 'bc', 'sign', 'scan', 'close', 'count', 'change', 'warn', 'search', 'delay', 'ob', 'sby'].indexOf(r.tab) < 0) return false;
      if (!int(r.scans, 0, 10) || !int(r.ppIdx == null ? 0 : r.ppIdx, 0, 10)) return false;
