    var swo = $('#w-swold'); if (swo) swo.onclick = function () { if (!wbLive(c)) return; sfx.ng(); wbStrike('wb-swap-old', L('機体が変わったのに前の承認版をそのまま使おうとしました。', '기체가 바뀌었는데 이전 승인판을 그대로 쓰려 했습니다.', 'Tried to keep the previous accepted sheet after the aircraft change.'), 'passenger/3-4'); wbEvtMark('swap'); wbCall('cap', L('登録記号が違います。この機体の数値で作り直してください。', '등록 기호가 다릅니다. 이 기체 수치로 다시 만들어 주세요.', 'Wrong registration. Redo it with this aircraft’s figures.'), 'cap_swold'); $('#w-evmsg').innerHTML = '<div class="why bad">' + esc(tx(L('前の承認は無効です。新しい機体の数値で再作成してください。', '이전 승인은 무효입니다. 새 기체 수치로 재작성하세요.', 'The previous acceptance is void. Reissue with the new aircraft’s figures.'))) + '</div>'; };
