    f.roster.forEach(function (p) { var ok = mode === 'acc' ? ['checkedIn', 'boarded', 'noshow'].indexOf(p.status) >= 0 : p.status === 'boarded'; if (ok && p.zone != null) { o.ad++; o.z[p.zone]++; } });
