  function dpEval(icao, etaH) { return DP.airportEval({ icao: icao, taf: dpTaf(icao), apps: dpApps(icao, etaH), closed: (dpP().notam || []).filter(function (n) { return n.closeAll && n.ap === icao && n.win; }).map(function (n) { return n.win; }) }, etaH); }
