    var Fcrit = dpD().fcritMore != null ? nBase + dpD().fcritMore : Math.round((nBase - dpD().fcritLess) / 10) * 10;   /* DAY 3 = 이 날 교체공항(MEL 적합) 기준 N + 카드 증가분(설계안 2A) */
