    h += '<p class="small">' + esc(tx(L('新しいEOBT ', '새 EOBT ', 'New EOBT '))) + '<b class="mono">' + dpUtcFull(rd.eobt) + '</b> · ' + esc(tx(L('目的地ETA ', '목적지 ETA ', 'Destination ETA '))) + '<b class="mono">' + dpUtcFull(rd.etaR) + '</b></p><p class="small">' + esc(tx(L('昨日の版がその空港の予定時刻の前後1時間を覆っているか、最新か、運用時間内かを確かめて選ぶ。', '어제 판이 그 공항 자체 시각 앞뒤 1시간을 덮는지, 최신인지, 운영시간 안인지 확인하고 고르기.', 'Check whether yesterday’s edition covers each airport’s own time ±1 h, whether it is the latest, and the operating hours.'))) + '</p>';
    h += row(rd.from, L('出発', '출발', 'departure'), rd.eobt) + row(p.dest, L('目的地', '목적지', 'destination'), rd.etaR) + p.cands.map(function (c) { return row(c, L('代替の候補', '교체공항 후보', 'alternate candidate'), rd.cv[c].etaR); }).join('');
