    S.cur = { p: u, mood: 100, mins: 0, tab: first[u.kind] || u.kind, notes: [], chk: {}, bags: [], flags: {}, acts: {}, selfFix: [], needSV: false, svDone: false };
    var M0 = M.times, at = null;
    if (u.kind === 'brf') at = cqA() + M0.brf; else if (u.kind === 'arr') at = cqA() + M0.arr; else if (u.kind === 'doc') at = cqS() + M0.doc; else if (u.kind === 'brd') at = cqS() + M0.brd; else if (u.kind === 'rec') at = cqS() + M0.rec;
    if (at != null && S.clock < at) S.clock = at;
